/**
 * Validation of the fielding / keeping age curves against real careers: the fixture (generated by
 * packages/ratings/src/analysis/fielding-progression.py) holds, for each starting age and horizon, the change the real
 * player-seasons show between the two ages (the fixed-effects age profile, not the smoothed curve) with its standard
 * error. Here Player.progress() is run forward for players starting at that age and the mean change compared.
 */

import { Player, type PlayerData } from "./player.js";
import { createRNG } from "./rng.js";
import type { FieldingKind } from "./fielding-progression.js";
import type { ProgressionGender } from "./progression.js";

export interface FieldingTarget {
  start: number;
  seasons: number;
  /** Real change in rating points between age `start` and `start + seasons` */
  change: number;
  se: number;
}
export type FieldingCohortFixture = Record<FieldingKind, Record<ProgressionGender, FieldingTarget[]>>;

export interface FieldingValidationRow extends FieldingTarget {
  kind: FieldingKind;
  gender: ProgressionGender;
  sim: number;
  /** |sim - real| within two standard errors plus 1.5 points */
  ok: boolean;
}

const BASE: PlayerData = {
  id: "v", name: "V", age: 27, country: "India", role: "batsman", isInternational: false, injured: false, injuryGamesLeft: 0,
  ratings: { battingIQ: 60, timing: 60, power: 60, running: 60, wicketTaking: 20, economy: 20, accuracy: 20, clutch: 50, fielding: 50, keeping: 50 },
};

/** Mean change of a rating over `seasons` seasons for players starting at `start` with the rating at 50 */
export function simulateFieldingChange(
  kind: FieldingKind, gender: ProgressionGender, start: number, seasons: number, runs: number, seed: number,
): number {
  const rng = createRNG(seed);
  let total = 0;
  for (let r = 0; r < runs; r++) {
    const p = new Player({ ...BASE, age: start, ratings: { ...BASE.ratings }, isWicketKeeper: kind === "keeping" });
    for (let s = 0; s < seasons; s++) p.progress({ rng, gender, historyLimit: 1 });
    total += (p.ratings[kind] ?? 50) - 50;
  }
  return total / runs;
}

export function validateFieldingProgression(fixture: FieldingCohortFixture, runs = 3000, seed = 5): FieldingValidationRow[] {
  const rows: FieldingValidationRow[] = [];
  for (const kind of ["fielding", "keeping"] as const) {
    for (const gender of ["male", "female"] as const) {
      for (const t of fixture[kind]?.[gender] ?? []) {
        const sim = simulateFieldingChange(kind, gender, t.start, t.seasons, runs, seed + t.start * 31 + t.seasons);
        rows.push({ ...t, kind, gender, sim, ok: Math.abs(sim - t.change) <= 2 * t.se + 1.5 });
      }
    }
  }
  return rows;
}

export function formatFieldingValidation(rows: FieldingValidationRow[]): string {
  const lines = ["kind     gender  start seasons  real (se)       sim     ok"];
  for (const r of rows) {
    lines.push(`${r.kind.padEnd(8)} ${r.gender.padEnd(7)} ${String(r.start).padStart(5)} ${String(r.seasons).padStart(7)}  ${r.change.toFixed(1).padStart(6)} (${r.se.toFixed(1)})  ${r.sim.toFixed(1).padStart(6)}  ${r.ok ? "yes" : "NO"}`);
  }
  return lines.join("\n");
}
